#!/usr/bin/env bash
# READ ONLY: MB bundle components and the products the Mindbody Plans model needs (for dev -> QA comparison)
echo "== COMPONENTS"
sf data query --query "SELECT ParentProduct.ProductCode, ChildProduct.ProductCode, ProductComponentGroup.Name, ProductComponentGroup.Code, ProductRelationshipType.Name, Quantity, MinQuantity, MaxQuantity, IsDefaultComponent, IsComponentRequired, IsQuantityEditable, Sequence, DoesBundlePriceIncludeChild, QuantityScaleMethod FROM ProductRelatedComponent WHERE ParentProduct.ProductCode LIKE 'MB-%' ORDER BY ParentProduct.ProductCode, ChildProduct.ProductCode" --target-org target --json | jq -r '.result.records[] | [.ParentProduct.ProductCode, .ChildProduct.ProductCode, .ProductComponentGroup.Name, .ProductComponentGroup.Code, .ProductRelationshipType.Name, .Quantity, .MinQuantity, .MaxQuantity, .IsDefaultComponent, .IsComponentRequired, .IsQuantityEditable, .Sequence, .DoesBundlePriceIncludeChild, .QuantityScaleMethod] | map(tostring) | join("|")'
echo "== PRODUCTS"
sf data query --query "SELECT ProductCode, Name, Family, Type, IsActive, ConfigureDuringSale, IsSoldOnlyWithOtherProds, UsageModelType, Description, BasedOn.Name, QuantityUnitOfMeasure FROM Product2 WHERE ProductCode IN ('MB-AIC','MB-F-CDB','MB-F-LEAD','MB-F-PAS','MB-F-RES','MB-F-AIC','MB-F-MKTG')" --target-org target --json | jq -c '.result.records[] | del(.attributes) | .BasedOn = (.BasedOn.Name // null)'
echo "== SELLING MODEL OPTIONS"
sf data query --query "SELECT Product2.ProductCode, ProductSellingModel.Name FROM ProductSellingModelOption WHERE Product2.ProductCode IN ('MB-AIC','MB-F-CDB','MB-F-LEAD','MB-F-PAS','MB-F-RES','MB-F-AIC')" --target-org target --json | jq -r '.result.records[] | "\(.Product2.ProductCode)|\(.ProductSellingModel.Name)"'
echo "== PRICEBOOK ENTRIES"
sf data query --query "SELECT Product2.ProductCode, Pricebook2.Name, ProductSellingModel.Name, CurrencyIsoCode, UnitPrice, IsActive FROM PricebookEntry WHERE Product2.ProductCode IN ('MB-AIC','MB-F-CDB','MB-F-LEAD','MB-F-PAS','MB-F-RES','MB-F-AIC')" --target-org target --json | jq -r '.result.records[] | "\(.Product2.ProductCode)|\(.Pricebook2.Name)|\(.ProductSellingModel.Name)|\(.CurrencyIsoCode)|\(.UnitPrice)|\(.IsActive)"'
echo "== CATEGORY"
sf data query --query "SELECT Product.ProductCode, ProductCategory.Name, ProductCategory.Catalog.Name FROM ProductCategoryProduct WHERE Product.ProductCode IN ('MB-AIC','MB-F-CDB','MB-F-LEAD','MB-F-PAS','MB-F-RES','MB-F-AIC')" --target-org target --json | jq -r '.result.records[] | "\(.Product.ProductCode)|\(.ProductCategory.Name)|\(.ProductCategory.Catalog.Name)"'
